SELECT DISTINCT 'all' population,COUNT(*) OVER() n,PERCENTILE_CONT(.25) WITHIN GROUP(ORDER BY wait_days) OVER() p25,PERCENTILE_CONT(.5) WITHIN GROUP(ORDER BY wait_days) OVER() median,PERCENTILE_CONT(.75) WITHIN GROUP(ORDER BY wait_days) OVER() p75 FROM facts WHERE has_ref AND referenced IS NOT NULL UNION ALL SELECT DISTINCT 'gained',COUNT(*) OVER(),PERCENTILE_CONT(.25) WITHIN GROUP(ORDER BY wait_days) OVER(),PERCENTILE_CONT(.5) WITHIN GROUP(ORDER BY wait_days) OVER(),PERCENTILE_CONT(.75) WITHIN GROUP(ORDER BY wait_days) OVER() FROM facts WHERE has_ref AND wait_days>0;
